/* Frontend prototype. Storage and approvals are browser-local; no APIs are called. */
const STORE='revodix.demo.v1';
let saved=null;try{saved=JSON.parse(localStorage.getItem(STORE));}catch{}
const state={page:'dashboard',role:saved?.role||'admin',threads:saved?.threads||structuredClone(sampleThreads),docs:saved?.docs||structuredClone(sampleDocs),feedback:saved?.feedback||structuredClone(sampleFeedback),audit:saved?.audit||structuredClone(sampleAudit),selected:1041,filter:'all',channel:'all',category:'all',search:'',period:'7',compose:'ai',mobileChat:false,sidebar:false,docSearch:'',docScope:'all',auditFilter:'all',emergency:saved?.emergency??false,threshold:saved?.threshold??99,modes:saved?.modes||Object.fromEntries(categories.map(c=>[c,'assisted'])),evaluation:saved?.evaluation||null,modelFailure:saved?.modelFailure??false,duplicates:saved?.duplicates||3,paused:saved?.paused||[],guidance:saved?.guidance||'확인된 제품과 공개 승인 문서의 범위 안에서만 답변합니다. 근거가 부족하면 필요한 정보를 재질문하고 담당자에게 넘깁니다. 재고·가격·납기는 추측하지 않습니다.'};
state.threads.forEach(t=>{t.originalDraft??=t.draft;t.history??=[];t.version??=1;if(t.status==='sent')t.approvedText=t.draft;});
state.channelModes=saved?.channelModes||Object.fromEntries(Object.keys(channels).map(c=>[c,'assisted']));
const names={dashboard:'운영 대시보드',inbox:'통합 문의함',knowledge:'매뉴얼·회사 지식',feedback:'수정 답변 검토',automation:'응대 모드·검수',reports:'분석 리포트',connections:'채널·운영 상태',audit:'처리 이력',settings:'사용자·운영 설정'};
const actor=()=>people[state.role];
const current=()=>state.threads.find(t=>t.id===state.selected)||state.threads[0];
const docsFor=t=>t.docs.map(id=>state.docs.find(d=>d.id===id)).filter(Boolean);
const count=st=>state.threads.filter(t=>t.status===st).length;
const isApproved=t=>!!t.approvedText&&t.approvedText===t.draft;
const isReadonly=()=>state.role==='viewer';
const badge=(text,kind='')=>`<span class="badge ${kind}">${esc(text)}</span>`;
const statusTag=t=>badge(statusNames[t.status],t.status==='held'?'amber':t.status==='failed'?'red':['review','approved'].includes(t.status)?'blue':'');
const ch=(key,compact=false)=>`<span class="channel-badge ${key}" title="${esc(channels[key].detail)}">${icon(channels[key].icon)}${compact?'':`<span>${channels[key].name}</span>`}</span>`;
const avatar=name=>`<span class="avatar">${esc(name.slice(-2))}</span>`;
function persist(){try{localStorage.setItem(STORE,JSON.stringify({threads:state.threads,docs:state.docs,feedback:state.feedback,audit:state.audit,role:state.role,emergency:state.emergency,threshold:state.threshold,modes:state.modes,channelModes:state.channelModes,evaluation:state.evaluation,modelFailure:state.modelFailure,duplicates:state.duplicates,paused:state.paused,guidance:state.guidance}));}catch{}}
function timeNow(){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date());}
function record(kind,target,detail){state.audit.unshift({id:Date.now()+Math.random(),time:timeNow(),actor:actor().name,kind,target,detail});persist();}
function permission(admin=false){if(isReadonly()||admin&&state.role!=='admin'){toast(admin?'관리자만 이 작업을 승인할 수 있습니다.':'조회 담당자는 정보를 확인할 수 있습니다. 프로필에서 데모 권한을 변경해 보세요.');return false;}return true;}
function invalidate(t,reason){if(t.approvedText){if(t.status==='sent'&&!t.history.length)t.history.push({actor:t.approvedBy||t.owner,text:t.draft,time:(t.sentAt||'이전')+' · 이전 데모 발송'});t.approvedText=null;t.status='review';record('승인 해제',`문의 #RV-${t.id}`,reason);}}
function sourceChecks(t){const docs=docsFor(t),pub=docs.filter(d=>d.active&&d.scope==='public');return [{name:'적용 제품 확인',ok:t.product!=='제품 미확인',note:t.product},{name:'공개 근거 확인',ok:pub.length>0&&t.rag!=='insufficient'&&t.rag!=='restricted',note:t.rag==='restricted'?'사내 전용 자료 공개 차단':pub.length?`${pub.length}개 공개 문서`:'공개 근거 없음'},{name:'최신 버전·활성 상태',ok:docs.length>0&&docs.every(d=>d.active),note:docs.length?docs.every(d=>d.active)?'활성 문서 확인':'비활성 문서 포함':'담당자 확인 필요'},{name:'답변 가능 범위',ok:t.rag==='supported',note:t.rag==='supported'?'근거 내 안내':t.checkReason}];}
function autoEligible(t){return t.rag==='supported'&&sourceChecks(t).every(c=>c.ok)&&!state.emergency&&!state.paused.includes(t.channel);}
function effectiveMode(t){const mode=state.modes[t.category],channelMode=state.channelModes[t.channel];return mode==='manual'||channelMode==='manual'?'수동 응대':mode==='auto'&&channelMode==='auto'?'자동 · 발송 전 검수':'반자동 · 담당자 승인';}
function channelModePanel(){return `<section class="panel spacing"><header><div><h2>채널별 응대 모드</h2><p>채널과 문의 유형이 모두 자동인 경우에만 자동 검수 대상으로 분류합니다. 수동 설정을 우선합니다.</p></div></header><div class="channel-mode-grid">${Object.entries(channels).map(([key,c])=>`<div>${ch(key)}<select class="select" data-input="channel-mode" data-channel="${key}" aria-label="${c.name} 채널 응대 모드" ${state.role!=='admin'?'disabled':''}><option value="manual" ${state.channelModes[key]==='manual'?'selected':''}>수동 응대</option><option value="assisted" ${state.channelModes[key]==='assisted'?'selected':''}>반자동 · 승인</option><option value="auto" ${state.channelModes[key]==='auto'?'selected':''}>자동 · 검수</option></select></div>`).join('')}</div></section>`;}
function navItem(page,label,ico,counter=''){return `<a href="#${page}" data-page="${page}" class="nav-link ${state.page===page?'active':''}" ${state.page===page?'aria-current="page"':''}>${icon(ico)}<span>${label}</span>${counter!==''?`<small>${counter}</small>`:''}</a>`;}
function renderShell(){
 $('#app').innerHTML=`<div class="app-shell"><aside class="sidebar ${state.sidebar?'open':''}"><a class="brand" href="#dashboard" data-page="dashboard"><span class="brand-symbol">R</span><span>REVODIX<small>통합 문의 관리</small></span></a><button class="workspace" data-action="workspace">${icon('building')}<span><strong>레보딕스 고객지원</strong><small>맞춤 구축 데모</small></span>${icon('down')}</button><div class="nav-group"><span class="nav-label">문의 운영</span>${navItem('dashboard','운영 대시보드','grid')}${navItem('inbox','통합 문의함','inbox',state.threads.filter(t=>t.status!=='sent').length)}${navItem('reports','분석 리포트','chart')}</div><div class="nav-group"><span class="nav-label">지식·응대 품질</span>${navItem('knowledge','매뉴얼·회사 지식','book')}${navItem('feedback','수정 답변 검토','edit',state.feedback.filter(f=>f.status==='pending').length)}${navItem('automation','응대 모드·검수','shield')}</div><div class="nav-group"><span class="nav-label">시스템 관리</span>${navItem('connections','채널·운영 상태','plug')}${navItem('audit','처리 이력','clock')}${navItem('settings','사용자·운영 설정','gear')}</div><div class="sidebar-bottom"><div class="operation-card"><span>${icon('shield')}현재 운영 방식</span><strong>${state.emergency?'자동 발송 중지':'담당자 검토 후 발송'}</strong><small>${state.emergency?'승인 검토는 계속할 수 있어요.':'문의 유형별로 자동 전환을 검토합니다.'}</small><button data-page="automation">운영 설정${icon('arrow')}</button></div><button class="help-link" data-action="guide">${icon('help')}데모 사용 가이드</button><button class="profile" data-action="profile">${avatar(actor().name)}<span><strong>${actor().name}</strong><small>${actor().role} · 예시 사용자</small></span>${icon('more')}</button></div></aside><button class="sidebar-scrim ${state.sidebar?'visible':''}" data-action="sidebar" aria-label="메뉴 닫기"></button><main class="main"><header class="topbar"><button class="icon-button mobile-menu" data-action="sidebar" aria-label="메뉴 열기">${icon('menu')}</button><div class="breadcrumb"><span>레보딕스</span>${icon('chevron')}<strong>${names[state.page]}</strong></div><div class="top-actions"><button class="global-search" data-action="search" aria-label="문의·문서 검색">${icon('search')}<span>문의·문서 검색</span><small>⌘ K</small></button>${badge('DEMO')}<button class="icon-button" data-action="profile" aria-label="데모 사용자 권한">${icon('people')}</button></div></header><div class="demo-strip"><span>${icon('file')}샘플 문의·가상 장비 매뉴얼로 구성된 레보딕스 전용 데모</span><button data-action="about">데모 범위</button></div><div id="page-root"></div></main></div>`;
 renderPage();
}
function heading(title,description,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${description}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;}
function footer(){return '<footer class="page-footer"><span>레보딕스 전용 통합 문의 관리</span><span>실제 고객 메시지·LLM·외부 API는 연결되지 않은 데모입니다.</span></footer>';}
function periodSelect(){return `<select class="select small" data-input="period" aria-label="조회 기간"><option value="7" ${state.period==='7'?'selected':''}>최근 7일</option><option value="30" ${state.period==='30'?'selected':''}>최근 30일</option></select>`;}
function visiblePeriod(){return state.threads.filter(t=>t.date>=(state.period==='7'?'2026-10-08':'2026-09-15'));}
function inquiryTable(list=state.threads.slice(0,5)){return `<div class="table-scroll"><table><thead><tr><th>고객·회사</th><th>문의 내용</th><th>채널</th><th>처리 상태</th><th>담당자</th></tr></thead><tbody>${list.map(t=>`<tr data-action="thread" data-id="${t.id}" tabindex="0" aria-label="${esc(t.name)}의 ${esc(t.subject)} 문의"><td><strong>${esc(t.name)}</strong><small>${esc(t.company)}</small></td><td class="subject">${esc(t.subject)}<small>${esc(t.category)} · ${esc(t.product)}</small></td><td>${ch(t.channel)}</td><td>${statusTag(t)}</td><td>${esc(t.owner)}</td></tr>`).join('')}</tbody></table></div>`;}
function dashboard(){const list=visiblePeriod(),queue=state.threads.filter(t=>['review','approved'].includes(t.status)),held=state.threads.filter(t=>['held','failed'].includes(t.status));return `<div class="content">${heading('문의가 답변으로 이어지는 곳','채널별 문의를 확인하고, 근거를 검토해 다음 답변을 준비하세요.',`<button class="btn" data-action="export">${icon('download')}리포트 내보내기</button>${periodSelect()}`)}<div class="metrics">${[['조회 기간 문의',list.length,'건','inbox','4개 문의 채널'],['검토가 필요한 답변',queue.length,'건','edit','담당자 승인 대기'],['보류된 문의',count('held'),'건','shield','근거·제품 정보 확인 필요'],['답변 완료',count('sent'),'건','checkCircle','샘플 처리 이력 기준']].map(([n,v,u,i,d])=>`<article class="metric"><span>${n}<i>${icon(i)}</i></span><strong>${v}<small>${u}</small></strong><p>${d}</p></article>`).join('')}</div><div class="dashboard-grid"><section class="panel"><header><div><h2>채널별 문의 현황</h2><p>조회 기간 내 샘플 문의 ${list.length}건</p></div>${badge('4개 채널')}</header><div class="channel-bars">${Object.entries(channels).map(([key,c])=>{const n=list.filter(t=>t.channel===key).length;return `<button class="channel-bar" data-action="channel-filter" data-channel="${key}"><span>${ch(key)}<small>${c.detail}</small></span><div><i style="width:${Math.max(n/list.length*100,5)}%;background:${c.color}"></i></div><strong>${n}<small>건</small></strong></button>`;}).join('')}</div><div class="panel-note">홈페이지 문의는 이메일로 회신하는 흐름입니다.</div></section><section class="panel"><header><div><h2>답변 검토를 기다리고 있어요</h2><p>매뉴얼 근거와 초안을 함께 확인하세요.</p></div>${badge(queue.length+'건','blue')}</header><div class="approval-list">${queue.slice(0,3).map(t=>`<button data-action="thread" data-id="${t.id}">${avatar(t.name)}<span><strong>${esc(t.name)}<small>${channels[t.channel].name}</small></strong><p>${esc(t.subject)}</p></span>${icon('chevron')}</button>`).join('')||'<div class="empty">승인 대기 답변이 없습니다.</div>'}</div><div class="panel-action"><button class="btn pale" data-action="review-queue">승인 대기 답변 보기${icon('arrow')}</button></div></section></div><section class="attention-box"><div>${icon('shield')}<span><strong>확인이 필요한 문의 ${held.length}건</strong><p>근거 부족·공개 범위·발송 실패를 담당자에게 연결합니다.</p></span></div><button class="text-button" data-action="held-queue">보류·실패 문의 확인${icon('arrow')}</button></section><section class="panel"><header><div><h2>최근 들어온 문의</h2><p>제품·문의 유형과 처리 상태를 한눈에 확인하세요.</p></div><button class="text-button" data-page="inbox">전체 문의${icon('arrow')}</button></header>${inquiryTable()}</section>${footer()}</div>`;}
function filtered(){return state.threads.filter(t=>(state.filter==='all'||state.filter==='attention'&&['held','failed'].includes(t.status)||state.filter==='review'&&['review','approved'].includes(t.status)||state.filter==='mine'&&t.owner===actor().name||state.filter===t.status)&&(state.channel==='all'||state.channel===t.channel)&&(state.category==='all'||state.category===t.category)&&`${t.name} ${t.company} ${t.subject} ${t.product}`.toLowerCase().includes(state.search.toLowerCase()));}
function inboxList(){const list=filtered();return `<aside class="inbox-list"><div class="inbox-search">${icon('search')}<input data-input="inquiry-search" value="${esc(state.search)}" aria-label="문의 검색" placeholder="고객, 제품, 문의 검색"></div><div class="inbox-filters"><button data-action="list-filter" data-filter="all" class="${state.filter==='all'?'active':''}">전체</button><button data-action="list-filter" data-filter="review" class="${state.filter==='review'?'active':''}">승인 대기</button><button data-action="list-filter" data-filter="attention" class="${state.filter==='attention'?'active':''}">확인 필요</button><button data-action="list-filter" data-filter="mine" class="${state.filter==='mine'?'active':''}">내 담당</button></div><div class="list-results" id="list-results">${threadItems(list)}</div><div class="list-count">${list.length}건의 샘플 문의</div></aside>`;}
function threadItems(list){return list.map(t=>`<button class="thread-item ${state.selected===t.id?'selected':''}" data-action="thread" data-id="${t.id}"><span class="thread-top">${ch(t.channel,true)}<strong>${esc(t.name)}</strong><small>${t.received}</small></span><strong class="thread-subject">${esc(t.subject)}</strong><p>${esc(t.summary)}</p><span class="thread-bottom">${statusTag(t)}<small>${esc(t.owner)}</small></span></button>`).join('')||'<div class="empty">해당하는 문의가 없습니다.</div>';}
function sourceLinks(t){const docs=docsFor(t).filter(d=>d.scope==='public'&&d.active);return docs.map(d=>`<button data-action="doc" data-id="${d.id}">${icon('file')}<span>${esc(d.title)}<small>v${esc(d.version)} · ${esc(d.page)}쪽</small></span>${icon('external')}</button>`).join('')||'<p class="no-source">확인된 공개 근거가 없습니다. 담당자가 직접 검토해 주세요.</p>';}
function conversation(){const t=current(),approved=isApproved(t);return `<section class="conversation"><header class="conversation-header"><button class="icon-button mobile-back" data-action="inbox-back" aria-label="문의 목록으로">${icon('back')}</button><div><h2>${esc(t.subject)}</h2><p>${esc(t.name)} · ${esc(t.company)} · #RV-${t.id}</p></div><button class="icon-button" data-action="thread-detail" aria-label="고객 정보와 근거 보기">${icon('more')}</button></header><div class="conversation-scroll"><div class="thread-summary"><strong>${icon('file')}문의 요약</strong><p>${esc(t.summary)}</p></div><div class="message-time">${t.date} · ${channels[t.channel].detail}</div><div class="message">${avatar(t.name)}<div><span>${esc(t.name)}<small>${t.received}</small></span><p>${esc(t.message)}</p></div></div>${t.followup?`<div class="message">${avatar(t.name)}<div><span>${esc(t.name)}<small>후속 질문</small></span><p>${esc(t.followup)}</p></div></div>`:''}${t.attachments.length?`<div class="attachments">${t.attachments.map((a,i)=>`<button data-action="attachment" data-index="${i}">${icon('file')}<span>${esc(a.name)}<small>담당자 직접 확인</small></span>${icon('external')}</button>`).join('')}</div>`:''}${t.history.map(h=>`<div class="message outgoing">${avatar(h.actor)}<div><span>${esc(h.actor)}<small>${esc(h.time)}</small></span><p>${esc(h.text)}</p></div></div>`).join('')}${t.status==='sent'&&!t.history.length?`<div class="message outgoing">${avatar(t.owner)}<div><span>${esc(t.owner)}<small>${t.sentAt} · 데모 발송</small></span><p>${esc(t.draft)}</p></div></div>`:''}${t.note?`<div class="internal-note">${icon('lock')}${esc(t.note)}</div>`:''}</div><div class="composer"><div class="composer-heading"><strong>${icon(state.compose==='ai'?'spark':'edit')}${state.compose==='ai'?'매뉴얼을 참고한 답변 초안':'담당자 직접 답변'}</strong><div class="segmented"><button data-action="compose" data-mode="ai" class="${state.compose==='ai'?'active':''}">AI 초안</button><button data-action="compose" data-mode="manual" class="${state.compose==='manual'?'active':''}">직접 작성</button></div></div><div class="draft-box ${state.compose==='manual'?'manual':''}"><div class="draft-top"><span id="approval-state">${approved?'발송 승인 · 수정 시 재승인 필요':'검토 후 승인 필요'} · v${t.version}</span><button class="text-button" data-action="regenerate" ${isReadonly()?'disabled':''}>${icon('refresh')}초안 다시 생성</button></div><textarea id="reply-draft" aria-label="답변 초안" data-input="draft" ${isReadonly()?'readonly':''}>${esc(t.draft)}</textarea><div class="source-chips">${docsFor(t).filter(d=>d.active&&d.scope==='public').map(d=>`<button data-action="doc" data-id="${d.id}">${icon('book')}${esc(d.title)} · ${esc(d.page)}쪽</button>`).join('')||'<span>확인된 공개 근거 없음 · 담당자 확인</span>'}</div></div><div class="composer-status"><span>${t.status==='failed'?icon('refresh'):icon('shield')}${t.status==='failed'?esc(t.failure):autoEligible(t)?'공개 근거 확인 · 담당자 승인 대기':esc(t.checkReason)}</span></div><div class="composer-actions"><div><button class="btn" data-action="hold" ${isReadonly()?'disabled':''}>보류</button><button class="btn" data-action="reject" ${isReadonly()?'disabled':''}>반려</button></div><div><button class="btn ${approved?'':'pale'}" data-action="approve" ${isReadonly()||approved?'disabled':''}>${icon('check')}승인하기</button><button class="btn primary" id="send-button" data-action="send" ${isReadonly()||!approved||t.status==='sent'?'disabled':''}>${icon('send')}${t.status==='failed'?'재발송':'발송'}</button></div></div><p class="composer-note">승인과 지식 반영은 별도 절차입니다. 데모 발송은 외부로 전송되지 않습니다.</p></div></section>`;}
function inspector(){const t=current();return `<aside class="inspector">${inspectorContent(t)}</aside>`;}
function inspectorContent(t){return `<section><h3>고객·제품 정보</h3><div class="customer-name">${avatar(t.name)}<span><strong>${esc(t.name)}</strong><small>${esc(t.company)}</small></span></div><dl><dt>모델명</dt><dd>${esc(t.product)}</dd><dt>문의 유형</dt><dd>${esc(t.category)}</dd><dt>담당자</dt><dd><button class="text-button" data-action="assign">${esc(t.owner)}${icon('down')}</button></dd><dt>운영 모드</dt><dd>${effectiveMode(t)}</dd><dt>회신 채널</dt><dd>${t.channel==='web'?'이메일 회신':channels[t.channel].name}</dd></dl>${t.linked?`<button class="linked-customer" data-action="linked">${icon('link')}확인된 이메일 고객 이력${icon('arrow')}</button>`:''}<button class="text-button" data-action="note">${icon('edit')}내부 메모 ${t.note?'수정':'추가'}</button></section><section><h3>답변 근거 문서</h3><div class="source-list">${sourceLinks(t)}</div>${t.rag==='restricted'?'<div class="inline-warning">사내 전용 문서를 고객 답변에 사용하지 않습니다.</div>':''}</section><section><h3>발송 전 확인</h3><div class="checks">${sourceChecks(t).map(c=>`<div class="check-item ${c.ok?'ok':'needs'}">${icon(c.ok?'checkCircle':'shield')}<span><strong>${c.name}</strong><small>${esc(c.note)}</small></span></div>`).join('')}</div></section><section><h3>처리 흐름</h3><div class="approval-steps"><span class="done">접수</span><i></i><span class="done">초안</span><i></i><span class="${isApproved(t)?'done':''}">승인</span><i></i><span class="${t.status==='sent'?'done':''}">발송</span></div><small class="muted">자동 검수 미통과 문의는 담당자가 확인합니다.</small></section>`;}
function inbox(){return `<div class="content inbox-content">${heading('통합 문의함','대화와 매뉴얼 근거를 함께 확인하며 답변을 검토하세요.',`<select class="select small" data-input="channel" aria-label="채널 필터"><option value="all">모든 채널</option>${Object.entries(channels).map(([k,c])=>`<option value="${k}" ${state.channel===k?'selected':''}>${c.name}</option>`).join('')}</select><select class="select small" data-input="category" aria-label="문의 유형 필터"><option value="all">모든 유형</option>${categories.map(c=>`<option ${state.category===c?'selected':''}>${c}</option>`).join('')}</select>`)}<div class="inbox-layout ${state.mobileChat?'show-conversation':''}">${inboxList()}${conversation()}${inspector()}</div></div>`;}
function navigate(page){if(!names[page])page='dashboard';state.page=page;state.sidebar=false;if(page==='inbox')state.mobileChat=false;history.replaceState(null,'',`#${page}`);renderShell();window.scrollTo(0,0);}
function openThread(id){state.selected=Number(id);state.mobileChat=true;state.compose='ai';state.page='inbox';state.sidebar=false;history.replaceState(null,'','#inbox');renderShell();}
function renderPage(){const pages={dashboard,inbox,knowledge,feedback,automation,reports,connections,audit,settings};$('#page-root').innerHTML=pages[state.page]();if(state.page==='inbox')requestAnimationFrame(()=>{const c=$('.conversation-scroll');if(c)c.scrollTop=c.scrollHeight;});}
let returnFocus=null,toastTimeout;
function toast(text){$('#toast-region').innerHTML=`<div class="toast">${icon('checkCircle')}${esc(text)}</div>`;clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast-region').innerHTML='',4500);}
function modal(title,body,buttons='',large=false){returnFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${large?'large':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header><h2 id="modal-title">${esc(title)}</h2><button class="icon-button" data-action="close" aria-label="닫기">${icon('close')}</button></header><div class="modal-body">${body}</div>${buttons?`<footer>${buttons}</footer>`:''}</section></div>`;document.body.style.overflow='hidden';requestAnimationFrame(()=>$('.modal input,.modal textarea,.modal button')?.focus());}
function closeModal(){$('#modal-root').innerHTML='';document.body.style.overflow='';if(returnFocus?.isConnected)returnFocus.focus();}
const cancel='<button class="btn" data-action="close">취소</button>';
